import { FC } from 'react';
import { useSceneCalculations } from '../hooks';

interface Props {
  proposal?: Proposal;
}

export const Scene: FC<Props> = ({ proposal }) => {
  const { scaleX, scaleY, positionY, nodes, materials } =
    useSceneCalculations(proposal);

  if (!nodes) return null;

  return (
    <group dispose={null}>
      <group position={[0.642, 1.856, -4.406]} scale={[7.144, 1.847, 4.243]}>
        <mesh
          castShadow
          receiveShadow
          geometry={nodes.Cube002.geometry}
          material={materials['09 Zid']}
          scale={[scaleX, scaleY, 1]}
          position={[0, positionY, 0]}
        />
        <mesh
          castShadow
          receiveShadow
          geometry={nodes.Cube002_1.geometry}
          material={materials['Wood Floor']}
        />
      </group>
      <mesh
        castShadow
        receiveShadow
        geometry={nodes.Pod_vani.geometry}
        material={materials['Concrete tile']}
        position={[0.557, 0.007, 0.948]}
        scale={[3.148, 1, 1.113]}
      />
      <mesh
        castShadow
        receiveShadow
        geometry={nodes.Kućni_broj.geometry}
        material={materials['01 Boja vrata RAL7016']}
        position={[-0.93, 1.509, 0.158]}
        rotation={[Math.PI / 2, 0, 0]}
        scale={0.003}
      />
      <mesh
        castShadow
        receiveShadow
        geometry={nodes.Pod_vani001.geometry}
        material={materials['Concrete tile.001']}
        position={[-5.741, 0.007, 0.948]}
        scale={[3.148, 1, 1.113]}
      />
      <mesh
        castShadow
        receiveShadow
        geometry={nodes.Pod_vani002.geometry}
        material={materials['Concrete tile.002']}
        position={[6.856, 0.007, 0.948]}
        scale={[3.148, 1, 1.113]}
      />
      <group position={[2.057, 0, 0.594]} scale={0.332}>
        <group position={[-0.012, 0.982, 0.007]} scale={3.014}>
          <mesh
            castShadow
            receiveShadow
            geometry={nodes.Mesh022.geometry}
            material={materials.Fiber}
          />
          <mesh
            castShadow
            receiveShadow
            geometry={nodes.Mesh022_1.geometry}
            material={materials['FIber Alpha']}
          />
        </group>
        <mesh
          castShadow
          receiveShadow
          geometry={nodes.Leaves.geometry}
          material={materials.Daun}
          position={[0.144, 2.892, 0.136]}
          scale={3.014}
        />
        <mesh
          castShadow
          receiveShadow
          geometry={nodes.Soil.geometry}
          material={materials.Soil_1}
          position={[-0.013, 0.844, 0.008]}
          scale={3.014}
        />
        <mesh
          castShadow
          receiveShadow
          geometry={nodes.Vase.geometry}
          material={materials['Glazed ceramic']}
          position={[0, 0.457, 0]}
          scale={3.014}
        >
          <mesh
            castShadow
            receiveShadow
            geometry={nodes.Soil001.geometry}
            material={materials.Soil_1}
            position={[-0.039, 0.129, 0.003]}
          />
        </mesh>
      </group>
      <group position={[-0.708, 0, -0.731]}>
        <mesh
          castShadow
          receiveShadow
          geometry={nodes.ground001.geometry}
          material={materials['TT_checker_1024x1024_UV_GRID.001']}
        />
        <mesh
          castShadow
          receiveShadow
          geometry={nodes.plant001.geometry}
          material={materials.leave_1_MatSG}
        />
        <mesh
          castShadow
          receiveShadow
          geometry={nodes.pot001.geometry}
          material={materials['TT_checker_1024x1024_UV_GRID.001']}
        />
      </group>
    </group>
  );
};

