import { ThreeElements } from '@react-three/fiber';

type ExtendedDirectionalLightProps = ThreeElements['directionalLight'] & {
  'shadow-bias'?: number;
  'shadow-mapSize-width'?: number;
  'shadow-mapSize-height'?: number;
};

const front: ExtendedDirectionalLightProps = {
  position: [0.793, 1.762, 5.56],
  visible: true,
  intensity: 3,
  castShadow: true,
  color: 'ffffff',
  'shadow-bias': -0.0001,
  'shadow-mapSize-width': 4096,
  'shadow-mapSize-height': 4096,
};

export const lights = { front };

