1	import { FC } from 'react';
2	import { lights } from '../../const';
3	import type { DoorSceneControls } from './useDoorSceneControls';
4	
5	interface Props {
6	  isFront: boolean;
7	  isNightMode: boolean;
8	  controls: DoorSceneControls;
9	}
10	
11	export const DoorSceneLights: FC<Props> = ({
12	  isFront,
13	  isNightMode,
14	  controls,
15	}) => {
16	  const {
17	    dayKeyX,
18	    dayKeyY,
19	    dayKeyZ,
20	    dayKeyIntensity,
21	    dayDetailX,
22	    dayDetailY,
23	    dayDetailZ,
24	    dayDetailIntensity,
25	    dayAmbIntensity,
26	    dayHemiIntensity,
27	    nightDirIntensity,
28	    nightAmbIntensity,
29	    nightHemiIntensity,
30	  } = controls;
31	
32	  if (isFront) {
33	    return (
34	      <>
35	        {/* Key light — raking from the side to reveal engraved details */}
36	        <directionalLight
37	          {...lights.front}
38	          position={[dayKeyX, dayKeyY, dayKeyZ] as [number, number, number]}
39	          castShadow
40	          intensity={isNightMode ? nightDirIntensity : dayKeyIntensity}
41	          color={isNightMode ? '#a9bce0' : '#ffffff'}
42	          shadow-bias={-0.0001}
43	          shadow-radius={3}
44	          shadow-mapSize-width={4096}
45	          shadow-mapSize-height={4096}
46	          shadow-camera-left={-3}
47	          shadow-camera-right={3}
48	          shadow-camera-top={4}
49	          shadow-camera-bottom={-2}
50	          shadow-camera-near={0.5}
51	          shadow-camera-far={25}
52	        />
53	        {/* Detail fill — from the opposite side, softer, prevents full black shadows */}
54	        {!isNightMode && (
55	          <directionalLight
56	            position={
57	              [dayDetailX, dayDetailY, dayDetailZ] as [number, number, number]
58	            }
59	            intensity={dayDetailIntensity}
60	            color="#e8eeff"
61	          />
62	        )}
63	        <ambientLight
64	          intensity={isNightMode ? nightAmbIntensity : dayAmbIntensity}
65	          color={isNightMode ? '#8d9ab0' : '#ffffff'}
66	        />
67	        <hemisphereLight
68	          color={isNightMode ? '#94a7c6' : '#ffffff'}
69	          groundColor={isNightMode ? '#1b2028' : '#888888'}
70	          intensity={isNightMode ? nightHemiIntensity : dayHemiIntensity}
71	        />
72	        <directionalLight
73	          position={[2, 2, -3]}
74	          intensity={isNightMode ? 0.22 : 0.35}
75	          color={isNightMode ? '#b0c1dd' : '#ffffff'}
76	        />
77	        <pointLight
78	          position={[-2, 2, -2]}
79	          intensity={isNightMode ? 0 : 0.3}
80	          distance={7}
