1	'use client';
2	
3	import { useMemo } from 'react';
4	import * as THREE from 'three';
5	import { useDoorMaterial } from '../../hooks/useDoorMaterials';
6	
7	// Door panel thickness in meters
8	const PANEL_THICKNESS = 0.05;
9	
10	interface GlassCutout {
11	  x: number; // center X position
12	  y: number; // center Y position
13	  width: number;
14	  height: number;
15	}
16	
17	interface ParametricDoorPanelProps {
18	  width: number; // in meters (1.0 - 1.25)
19	  height: number; // in meters (2.2 - 2.9)
20	  thickness?: number;
21	  color?: string;
22	  // Optional: Use material ID to load RAL material from Blender
23	  materialId?: string;
24	  glassCutouts?: GlassCutout[];
25	  position?: [number, number, number];
26	  side?: 'front' | 'back';
27	}
28	
29	/**
30	 * Creates a door panel geometry using THREE.Shape with holes for glass cutouts.
31	 * This approach avoids the stretching problem of scaling pre-made meshes.
32	 * Dimensions are in meters (1 Three.js unit = 1 meter).
33	 */
34	export const ParametricDoorPanel: React.FC<ParametricDoorPanelProps> = ({
35	  width,
36	  height,
37	  thickness = PANEL_THICKNESS,
38	  color = '#895129',
39	  materialId,
40	  glassCutouts = [],
41	  position = [0, 0, 0],
42	  side = 'front',
43	}) => {
44	  // Load Blender material if materialId is provided
45	  const blenderMaterial = useDoorMaterial(materialId);
46	
47	  const geometry = useMemo(() => {
48	    // Create the main panel shape (centered at origin)
49	    const shape = new THREE.Shape();
50	    const halfW = width / 2;
51	    const halfH = height / 2;
52	
53	    // Draw outer rectangle (counter-clockwise for front face)
54	    shape.moveTo(-halfW, -halfH);
55	    shape.lineTo(halfW, -halfH);
56	    shape.lineTo(halfW, halfH);
57	    shape.lineTo(-halfW, halfH);
58	    shape.closePath();
59	
60	    // Add holes for each glass cutout
61	    glassCutouts.forEach((cutout) => {
62	      const hole = new THREE.Path();
63	      const cx = cutout.x;
64	      const cy = cutout.y;
65	      const hw = cutout.width / 2;
66	      const hh = cutout.height / 2;
67	
68	      // Draw hole (clockwise to create a hole)
69	      hole.moveTo(cx - hw, cy - hh);
70	      hole.lineTo(cx - hw, cy + hh);
71	      hole.lineTo(cx + hw, cy + hh);
72	      hole.lineTo(cx + hw, cy - hh);
73	      hole.closePath();
74	
75	      shape.holes.push(hole);
76	    });
77	
78	    // Extrude to give thickness
79	    const extrudeSettings: THREE.ExtrudeGeometryOptions = {
80	      depth: thickness,
81	      bevelEnabled: false,
82	    };
83	
84	    const geom = new THREE.ExtrudeGeometry(shape, extrudeSettings);
85	
86	    // Center the geometry on Z axis
87	    geom.translate(0, 0, -thickness / 2);
88	
89	    return geom;
90	  }, [width, height, thickness, glassCutouts]);
91	
92	  return (
93	    <mesh
94	      geometry={geometry}
95	      position={position}
96	      rotation={side === 'back' ? [0, Math.PI, 0] : [0, 0, 0]}
97	      castShadow
98	      receiveShadow
99	    >
100	      {blenderMaterial ? (
101	        <primitive object={blenderMaterial} attach="material" />
102	      ) : (
103	        <meshStandardMaterial color={color} side={THREE.DoubleSide} />
104	      )}
105	    </mesh>
106	  );
107	};
108

