'use client';
import { EffectComposer, N8AO } from '@react-three/postprocessing';
import { FC } from 'react';

interface DoorPostProcessingProps {
  aoRadius: number;
  aoIntensity: number;
  distanceFalloff: number;
  isNightMode: boolean;
}

export const DoorPostProcessing: FC<DoorPostProcessingProps> = ({
  aoRadius,
  aoIntensity,
  distanceFalloff,
  isNightMode,
